effect.shader:
const vec3 LUMA = vec3(0.2126, 0.7152, 0.0722);

float hash21(vec2 p) { p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }

float cruz(vec2 p, float r) {
    float h = smoothstep(r, 0.0, abs(p.y)) * smoothstep(r * 3.0, 0.0, abs(p.x));
    float v = smoothstep(r, 0.0, abs(p.x)) * smoothstep(r * 3.0, 0.0, abs(p.y));
    return max(h, v);
}

void main() {
    vec4 orig = texture(inputImg, acScreenNorm);
    vec2 g = acScreenNorm * density;
    vec2 cell = floor(g);
    vec2 f = fract(g) - 0.5;
    float r = hash21(cell);
    float fase = r * 6.2831853;
    float pisc = pow(max(sin(acTime * speed + fase), 0.0), 3.0);

    float l = dot(orig.rgb, LUMA);
    float onde = smoothstep(threshold, threshold + 0.2, l);

    float estrela = cruz(f, 0.09 * size) * pisc * onde;
    fragColor = vec4(orig.rgb + tint.rgb * tint.a * estrela * 2.0, orig.a);
}
